#include <vector>
#include <cmath>
#include <stdexcept>
#include <string>

#include "sctl/math_utils.hpp"       // for sctl::atoreal

// Alpert hybrid Gauss-trapezoidal quadrature data (translated from MATLAB).
//
// Endpoint-correction nodes and weights for a uniform trapezoidal rule: the log
// tables correct an endpoint with a log singularity, the smooth tables correct a
// regular (non-singular) endpoint to high order. The rule assembly that consumes
// this data lives in QuadElemList::LogSingularQuad1D.
//
// Values are decimal string literals parsed at Real precision (sctl::atoreal), so nothing
// is truncated through double. Tables marked "refit in QuadReal" carry 34 digits, obtained by
// Newton on their exactness conditions sum_i w_i g(x_i) = T[g] -- for the log tables
// g = t^k and t^k log t with k < n, for the smooth tables g = t^k over the free unknowns
// (nodes sitting exactly on a grid point are pinned, not solved for). See
// debug-acccuracy/alpert-refine-all.cpp.

template <class Real> struct ExtraPtResult {
    std::vector<Real> ExtraNodes;
    std::vector<Real> ExtraWeights;
    int NodesToSkip = 0;
};

namespace alpert_detail {

template <class Real> void Fill(ExtraPtResult<Real>& r, const char* const* nds,
                               const char* const* wts, int n, int skip) {
    r.ExtraNodes.resize(n);
    r.ExtraWeights.resize(n);
    for (int i = 0; i < n; i++) {
        r.ExtraNodes[i] = sctl::atoreal<Real>(nds[i]);
        r.ExtraWeights[i] = sctl::atoreal<Real>(wts[i]);
    }
    r.NodesToSkip = skip;
}

} // namespace alpert_detail

